css:
.ob-progress-wrap {
  position: sticky; top: 0; z-index: 10;
  background: var(--bg); border-bottom: 1px solid var(--border-alt); padding: 18px 40px;
}
.ob-progress-top { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 12px; }
.ob-progress-top span { font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-dim); }
.ob-save-state { color: var(--accent) !important; }
.ob-progress { height: 3px; background: var(--border-alt); border-radius: 2px; overflow: hidden; }
.ob-progress-bar { height: 100%; width: 0; background: var(--accent); transition: width 0.35s ease; }

@media (max-width: 700px) {
  .ob-progress-wrap { padding-left: 20px; padding-right: 20px; }
}

.demo-controles { display: flex; gap: 12px; padding: 32px 40px; }
.demo-controles button {
  padding: 12px 22px; background: transparent; color: var(--text);
  border: 1px solid var(--border-alt); border-radius: 4px;
  font-family: 'JetBrains Mono', monospace; font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase;
}
.demo-controles button:hover { border-color: var(--accent); color: var(--accent); }

js:
export function initProgresso(passos) {
  const rotulo = document.getElementById('obPasso');
  const barra = document.getElementById('obBarra');
  let atual = 0;

  function pintar() {
    rotulo.textContent = 'Passo ' + (atual + 1) + ' de ' + passos.length + ' · ' + passos[atual];
    barra.style.width = (((atual + 1) / passos.length) * 100) + '%';
  }

  function ir(delta) {
    atual = Math.min(Math.max(atual + delta, 0), passos.length - 1);
    pintar();
  }

  pintar();
  return { ir: ir };
}

demo:
const wizard = initProgresso([
  'Sobre a empresa', 'Identidade', 'Conteúdo', 'Referências',
  'Estrutura', 'Domínio e hospedagem', 'Revisão'
]);
document.getElementById('obVoltar').addEventListener('click', function () { wizard.ir(-1); });
document.getElementById('obAvancar').addEventListener('click', function () { wizard.ir(1); });
